    private void handleGenericCircuitCase(
            CheckBox[] circuits,
            String[] suffixes,
            String structureCode,
            PurposeModel model,
            ArrayList<NewModel> listLT,
            LinearLayout layoutProposed,
            CheckBox proposedCheckBox,
            int capacity,
            int minCapacityForProposed
    ) {
        if (model.getSTATUS().equalsIgnoreCase("2")) {
            lockCircuitsByText(circuits, listLT);
        }

        setupCircuitsWithSuffixes(circuits, structureCode, suffixes);

        if (capacity >= minCapacityForProposed) {
            layoutProposed.setVisibility(View.VISIBLE);
            proposedCheckBox.setText(structureCode + suffixes[suffixes.length - 1]
                    .replace("_LTCKT_", "_LTCKT_"));
        }
    }

