    private void lockCircuitsByText(CheckBox[] circuits, ArrayList<NewModel> listLT) {
        boolean[] isLocked = new boolean[circuits.length];
        String[] circuitTexts = new String[circuits.length];

        // First, get all circuit texts
        for (int i = 0; i < circuits.length; i++) {
            circuitTexts[i] = circuits[i].getText().toString();
        }

        // Check which circuits are locked
        for (NewModel item : listLT) {
            String ltAvailable = item.getLT_AVAILABLE();
            for (int i = 0; i < circuitTexts.length; i++) {
                if (!isLocked[i] && ltAvailable.equalsIgnoreCase(circuitTexts[i])) {
                    isLocked[i] = true;
                }
            }
        }

        // Apply locking
        for (int i = 0; i < circuits.length; i++) {
            if (isLocked[i]) {
                circuits[i].setEnabled(false);
                circuits[i].setChecked(true);
            }
        }
    }

    private void setupCircuitsWithSuffixes(CheckBox[] circuits, String structureCode, String[] suffixes) {
        for (int i = 0; i < circuits.length; i++) {
            circuits[i].setVisibility(View.VISIBLE);
            circuits[i].setText(structureCode + suffixes[i]);
        }
    }


    private void handleLtCktUIUpdate(String noOfLtCkt, String selectedString, PurposeModel model, ArrayList<NewModel> listLT, String number, int poleCount, int LT_CKT_CODE_COUNT) {
        String structureCode = selectedString.split("~")[0];

        for (int i = 0; i < EstimatesHome.dtrFeederMasters.size(); i++) {
            if (!EstimatesHome.dtrFeederMasters.get(i).getDTR_STRUCTURE_CODE().equals(structureCode))
                continue;

            String capacityStr = EstimatesHome.dtrFeederMasters.get(i).getCAPACITY();
            int capacity = parseCapacity(capacityStr);

            handleLtCircuitCase(noOfLtCkt, structureCode, model, listLT, capacity, number, poleCount, LT_CKT_CODE_COUNT);
            break;
        }
    }


    private void setupCircuits(CheckBox[] circuits, String[] suffixes, String structureCode, PurposeModel model, ArrayList<NewModel> listLT) {
        // Set text for all circuits first
        for (int i = 0; i < circuits.length; i++) {
            circuits[i].setText(structureCode + suffixes[i]);
            circuits[i].setVisibility(View.VISIBLE);
        }

        // Handle locking for status "2"
        if (model.getSTATUS().equalsIgnoreCase("2")) {
            lockOccupiedCircuits(circuits, listLT);
        }
    }

    private void lockOccupiedCircuits(CheckBox[] circuits, ArrayList<NewModel> listLT) {
        for (CheckBox circuit : circuits) {
            if (isCircuitLocked(circuit.getText().toString(), listLT)) {
                circuit.setEnabled(false);
                circuit.setChecked(true);
            }
        }
    }

    private boolean isCircuitLocked(String circuitText, ArrayList<NewModel> listLT) {
        for (NewModel item : listLT) {
            if (item.getLT_AVAILABLE().equalsIgnoreCase(circuitText)) {
                return true;
            }
        }
        return false;
    }

    private void hideAllCircuits() {
        for (CheckBox circuit : circuitCheckBoxes) {
            circuit.setVisibility(View.GONE);
            circuit.setChecked(false);
        }
        //layout_proposed_lt_ckt_1.setVisibility(View.GONE);
    }


    //NEW DTR CHANGES BY CHANDU
    private void showAlertDialog(String titleStr, String messageStr, String voltage_level) {

        Dialog dialog = new Dialog(PrepareEstimate.this);
        View view = getLayoutInflater().inflate(R.layout.customized_dialog, null);
        dialog.setContentView(view);

        // Views
        TextView title = view.findViewById(R.id.title);
        TextView message = view.findViewById(R.id.message);
        TextView okBtn = view.findViewById(R.id.okBtn);
        TextView cancelBtn = view.findViewById(R.id.cancelBtn);
        TextView tv_est_no = view.findViewById(R.id.tv_est_no);
        TextView tv_gis_id = view.findViewById(R.id.tv_gis_id);

        tv_est_no.setText(getColoredText("Est No: ", st_est_no, this));
        tv_gis_id.setText(getColoredText("GIS ID: ", st_gis_id, this));
        // Set Data
        title.setText(titleStr);
        message.setText(messageStr);

        // Show both buttons
        okBtn.setVisibility(View.VISIBLE);
        cancelBtn.setVisibility(View.VISIBLE);

        okBtn.setText("OKAY");
        cancelBtn.setText("CANCEL");

        // OK Click
        okBtn.setOnClickListener(v -> {
            dialog.dismiss();
        });

        // CANCEL Click
        cancelBtn.setOnClickListener(v -> {
            dialog.dismiss();
        });

        dialog.setCancelable(true); // since original allows cancel

        // Transparent background
        if (dialog.getWindow() != null) {
            dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);
            DisplayMetrics displayMetrics = getResources().getDisplayMetrics();
            int width = (int) (displayMetrics.widthPixels * 0.90);
            dialog.getWindow().setLayout(
                    width,
                    ViewGroup.LayoutParams.WRAP_CONTENT
            );

        }

        dialog.show();
    }


