    private boolean checkProposedPoleCountForLT(String ltCode) {
        ArrayList<NewModel> listLT = databaseEstimates.getNewSurveyData(st_est_no, "LT", false, st_gis_id);
        boolean isLocked = false;
        for (NewModel item : listLT) {
            if (ltCode.equalsIgnoreCase(item.getLT_AVAILABLE())) {
                isLocked = true;
                break;
            }
        }
        return isLocked;
    }

    private boolean checkLTPolesCount(String DTR_CODE) {
        ArrayList<NewModel> listLT = databaseEstimates.getNewSurveyData(st_est_no, "LT", false, st_gis_id);
        boolean isLocked = false;
        for (NewModel item : listLT) {
            if (DTR_CODE.equalsIgnoreCase(item.getDTR_STRUCTURE_CODE())) {
                isLocked = true;
                break;
            }
        }
        return isLocked;
    }

