    private void openMoreInfoDialog(String voltage_level) {
        Dialog payDialog = new Dialog(this);
        DisplayMetrics displayMetrics = new DisplayMetrics();
        getWindowManager().getDefaultDisplay().getMetrics(displayMetrics);
        int height = displayMetrics.heightPixels;
        int width = displayMetrics.widthPixels;
        payDialog.setContentView(R.layout.more_info_dialog_11);
        payDialog.getWindow().setBackgroundDrawableResource(R.drawable.alert_dialog_bg);
        payDialog.getWindow().setLayout(width, height / 2);
        payDialog.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
        payDialog.getWindow().getAttributes().windowAnimations = R.style.DialogAnimation;
        TextView back_to_home = payDialog.findViewById(R.id.back_to_home);
        TextView new_bay_desc = payDialog.findViewById(R.id.new_bay_desc);
        TextView line_extension_desc = payDialog.findViewById(R.id.line_extension_desc);
        TextView header_2 = payDialog.findViewById(R.id.header_2);
        TextView header_1 = payDialog.findViewById(R.id.header_1);


        for (int i = 0; i < SurveyList.infoList.size(); i++) {
            if (SurveyList.infoList.get(i).getFEATURE().equalsIgnoreCase("FEEDER SURVEY TYPE")
                    && (SurveyList.infoList.get(i).getFEATURE_SUB_TYPE().equalsIgnoreCase("EXISTING")
                    || SurveyList.infoList.get(i).getFEATURE_SUB_TYPE().equalsIgnoreCase("Line Extension"))) {

                line_extension_desc.setVisibility(View.VISIBLE);
                header_1.setVisibility(View.VISIBLE);
                header_2.setVisibility(View.VISIBLE);

                line_extension_desc.setText(SurveyList.infoList.get(i).getDESCRIPTION());
                header_1.setText(SurveyList.infoList.get(i).getFEATURE_SUB_TYPE());
            }

            if ("33KV".equals(voltage_level)) {
                if (SurveyList.infoList.get(i).getFEATURE().equalsIgnoreCase("FEEDER SURVEY TYPE")
                        && (SurveyList.infoList.get(i).getFEATURE_SUB_TYPE().equalsIgnoreCase("PROPOSED") ||
                        SurveyList.infoList.get(i).getFEATURE_SUB_TYPE().equalsIgnoreCase("Bay Extension/New Feeder 33kv"))) {

                    new_bay_desc.setVisibility(View.VISIBLE);
                    header_1.setVisibility(View.VISIBLE);
                    header_2.setVisibility(View.VISIBLE);

                    new_bay_desc.setText(SurveyList.infoList.get(i).getDESCRIPTION());
                    header_2.setText(SurveyList.infoList.get(i).getFEATURE_SUB_TYPE());

                }

            } else {
                if (SurveyList.infoList.get(i).getFEATURE().equalsIgnoreCase("FEEDER SURVEY TYPE")
                        && (SurveyList.infoList.get(i).getFEATURE_SUB_TYPE().equalsIgnoreCase("PROPOSED") ||
                        SurveyList.infoList.get(i).getFEATURE_SUB_TYPE().equalsIgnoreCase("Bay Extension/New Feeder"))) {

                    new_bay_desc.setVisibility(View.VISIBLE);
                    header_1.setVisibility(View.VISIBLE);

                    new_bay_desc.setText(SurveyList.infoList.get(i).getDESCRIPTION());
                    header_2.setText(SurveyList.infoList.get(i).getFEATURE_SUB_TYPE());

                }
            }


        }

        payDialog.show();

        back_to_home.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                payDialog.dismiss();
            }
        });

    }

