    private void open33KVFeederMasterDialogNew(TextView edt_text) {
        ArrayList<String> filteredList = new ArrayList<>();
        HashMap<String, Integer> feederPoleMap = new HashMap<>();

        for (int i = 0; i < EstimatesHome.nearBy33kvModelsSS.size(); i++) {
            if (selectedSSCode.equals(EstimatesHome.nearBy33kvModelsSS.get(i).getEHT_SS_CODE())) {
                int polesCount = Integer.parseInt(EstimatesHome.nearBy33kvModelsSS.get(i).getPOLES().trim());
                String feederInfo = EstimatesHome.nearBy33kvModelsSS.get(i).getFEEDER_NAME_33KV() + "~" +
                        EstimatesHome.nearBy33kvModelsSS.get(i).getFEEDER_CODE_33KV();

                filteredList.add(feederInfo);
                feederPoleMap.put(feederInfo, polesCount);
            }
        }


        System.out.println("SELECTED_SS_CODE: " + selectedSSCode);

        if (filteredList.isEmpty()) {
            showNoFeedersDialog();

        } else {
            SearchableSpinner searchableSpinner = new SearchableSpinner(PrepareEstimate.this);
            searchableSpinner.setWindowTitle("SELECT FEEDER");

            searchableSpinner.setSpinnerListItems(filteredList);
            searchableSpinner.show();
            searchableSpinner.setOnItemSelectListener((position, selectedString) -> {
                int polesCount = feederPoleMap.get(selectedString);

                if (polesCount == 0) {
                    showSurveyNotInitiatedDialog(edt_text);

                } else {
                    edt_text.setText(selectedString);
                }
            });
        }
    }

