                for (DTRFeederMaster feeder : EstimatesHome.dtrFeederMasters) {
                    if (feeder.getDTR_STRUCTURE_CODE().equalsIgnoreCase(feederId)) {
                        modelLt.setFEEDER_NAME(feeder.getDTR_LOCATION());
                        break;
                    }
                }

                modelLt.setFEEDER_ID(feederId);
                modelLt.setLT_CKT_CODE(ltCktCode);

