    private void showAlertDialogForUncheckCondition() {

        Dialog dialog = new Dialog(this);
        View view = getLayoutInflater().inflate(R.layout.customized_dialog, null);
        dialog.setContentView(view);

        // Views
        TextView title = view.findViewById(R.id.title);
        TextView message = view.findViewById(R.id.message);
        TextView okBtn = view.findViewById(R.id.okBtn);
        TextView cancelBtn = view.findViewById(R.id.cancelBtn);
        TextView tv_est_no = view.findViewById(R.id.tv_est_no);
        TextView tv_gis_id = view.findViewById(R.id.tv_gis_id);

        tv_est_no.setText(getColoredText("Est No: ", st_est_no, this));
        tv_gis_id.setText(getColoredText("GIS ID: ", st_gis_id, this));

        // Set Data
        title.setText("Alert");
        message.setText("If you want to modify the data, first you need to delete existing poles.");

        // Show both buttons
        okBtn.setVisibility(View.VISIBLE);
        cancelBtn.setVisibility(View.VISIBLE);

        okBtn.setText("Yes");
        cancelBtn.setText("Close");

        // YES Click
        okBtn.setOnClickListener(v -> dialog.dismiss());

        // CLOSE Click
        cancelBtn.setOnClickListener(v -> dialog.cancel());

        dialog.setCancelable(true);

        // Transparent background + full width
        if (dialog.getWindow() != null) {
            dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);
            DisplayMetrics displayMetrics = getResources().getDisplayMetrics();
            int width = (int) (displayMetrics.widthPixels * 0.90);
            dialog.getWindow().setLayout(
                    width,
                    ViewGroup.LayoutParams.WRAP_CONTENT
            );
        }

        dialog.show();
    }

