    @Override
    public void onCheckedChanged(CompoundButton buttonView, boolean isChecked) {
        switch (buttonView.getId()) {
            case R.id.ch_33:
                if (ch_33.isChecked()) {

                    main_33kv_layout.setVisibility(View.VISIBLE);
                    //  main_lt_layout.setVisibility(View.GONE);

                } else {
                    if (!new_ch_11.isChecked()) {


                    }


                    ArrayList<NewModel> polesData = databaseEstimates.getNewSurveyData(st_est_no, "33KV", false, st_gis_id);
                    Gson gson = new GsonBuilder().setPrettyPrinting().create();
                    String json = gson.toJson(polesData);
                    //   Log.d("CHECK_DATA_IN_33KV", "onCreate: " + json);
                    if (polesData != null && !polesData.isEmpty()) {
                        showAlertDialogForUncheckCondition();
                        ch_33.setChecked(true);
                    } else {
                        main_33kv_layout.setVisibility(View.GONE);

                    }


                }
                break;
            case R.id.ch_11:
                if (ch_11.isChecked()) {
                    main_11kv_layout.setVisibility(View.VISIBLE);
                    // main_lt_layout.setVisibility(View.GONE);
                } else {


                    main_11kv_layout.setVisibility(View.GONE);
                    if (!ch_33.isChecked() && ch_lt.isChecked()) {
                        //  main_lt_layout.setVisibility(View.VISIBLE);
                    }
                }
                break;

            //NEW CODE
            case R.id.ch_lt:

                if (ch_lt.isChecked()) {

                    // Run dialog logic only when user clicks checkbox
                    if (ch_lt.isPressed()) {

                        if (LoginActivity.SURVEY_FROM.equalsIgnoreCase("SOLAR_DPR")) {
                            if (!new_ch_11.isChecked()) {
                                openAlertDialog(ch_lt);
                            }
                        }

                        if (!new_ch_33.isChecked() && !new_ch_11.isChecked()) {

                            if ("PV".equalsIgnoreCase(EST_TYPE) || "NP".equalsIgnoreCase(EST_TYPE)) {

                                boolean isStatus1 = "1".equalsIgnoreCase(model.getSTATUS());
                                boolean isStatus2Condition = "2".equalsIgnoreCase(model.getSTATUS());

                                if (isStatus1 || isStatus2Condition) {
                                    openAlertDialogOCP(ch_lt);
                                }
                            }
                        }
                    }

                    // PROPOSED DTR WITH LT CHANGES

                    if (new_ch_11.isChecked()) {

                        layout_lt_servey_type.setVisibility(View.VISIBLE);

                        if (sp_lt_servey_type.getSelectedItem().toString().equalsIgnoreCase("Yes")) {
                            main_lt_layout.setVisibility(View.VISIBLE);
                        }

                    } else if (new_ch_33.isChecked()) {

                        layout_lt_servey_type.setVisibility(View.GONE);
                        main_lt_layout.setVisibility(View.VISIBLE);

                    } else {

                        main_lt_layout.setVisibility(View.VISIBLE);
                    }

                } else {

                    sp_lt_servey_type.setSelection(0, true);
                    new_sp_no_of_dtr_lt.setSelection(0, true);

                    // PROPOSED DTR WITH LT CHANGES
                    layout_lt_servey_type.setVisibility(View.GONE);

                    ArrayList<NewModel> polesData =
                            databaseEstimates.getNewSurveyData(st_est_no, "LT", false, st_gis_id);

                    Gson gson = new GsonBuilder().setPrettyPrinting().create();
                    String json = gson.toJson(polesData);

                    if (polesData != null && !polesData.isEmpty()) {

                        showAlertDialogForUncheckCondition();
                        ch_lt.setChecked(true);

                    } else {

                        main_lt_layout.setVisibility(View.GONE);
                    }
                }

                break;


            //NEW ----
            // NEW CODE
            case R.id.new_ch_11:

                if (new_ch_11.isChecked()) {
                    new_layout_main_11.setVisibility(View.VISIBLE);
                    main_lt_layout.setVisibility(View.GONE);

                } else {

                    // Run dialog logic only if user clicked checkbox
                    if (new_ch_11.isPressed()) {

                        if (LoginActivity.SURVEY_FROM.equalsIgnoreCase("SOLAR_DPR")) {
                            if (ch_lt.isChecked()) {
                                openAlertDialog(ch_lt);
                            }
                        }

                        // GRID SURVEY CONDITION
                        if (ch_lt.isChecked()) {

                            if ("PV".equalsIgnoreCase(EST_TYPE) || "NP".equalsIgnoreCase(EST_TYPE)) {

                                if ("1".equalsIgnoreCase(model.getSTATUS()) ||
                                        "2".equalsIgnoreCase(model.getSTATUS())) {

                                    openAlertDialogOCP(ch_lt);
                                }
                            }
                        }
                    }

                    if (ch_lt.isChecked()) {
                        main_lt_layout.setVisibility(View.VISIBLE);
                        new_layout_main_11.setVisibility(View.GONE);
                    } else {
                        new_layout_main_11.setVisibility(View.GONE);
                    }
                }

                // PROPOSED DTR WITH LT CHANGES
                if (new_ch_11.isChecked() && ch_lt.isChecked()) {

                    layout_lt_servey_type.setVisibility(View.VISIBLE);

                    if (model != null && model.getFDR_PARTICULARS() != null) {

                        for (int j = 0; j < model.getFDR_PARTICULARS().size(); j++) {

                            if ("LT".equalsIgnoreCase(model.getFDR_PARTICULARS().get(j).getVOLTAGE_LEVEL())) {

                                sp_lt_servey_type.setSelection(1, true);

                            } else {

                                sp_lt_servey_type.setSelection(0, true);
                            }
                        }
                    }

                } else {

                    layout_lt_servey_type.setVisibility(View.GONE);
                }

                break;


            // NEW CODE
            case R.id.new_ch_33:

                if (new_ch_33.isChecked()) {

                    new_layout_main_33.setVisibility(View.VISIBLE);


                } else {

                    // Execute dialog logic only if user clicked the checkbox
                    if (new_ch_33.isPressed()) {

                        if (ch_lt.isChecked()) {

                            if ("PV".equalsIgnoreCase(EST_TYPE) || "NP".equalsIgnoreCase(EST_TYPE)) {

                                if ("1".equalsIgnoreCase(model.getSTATUS()) ||
                                        "2".equalsIgnoreCase(model.getSTATUS())) {

                                    openAlertDialogOCP(ch_lt);
                                }
                            }
                        }
                    }

                    if (ch_lt.isChecked()) {
                        main_lt_layout.setVisibility(View.VISIBLE);
                        new_layout_main_11.setVisibility(View.GONE);
                    }

                    ArrayList<NewModel> polesData =
                            databaseEstimates.getNewSurveyData(st_est_no, "33KV", false, st_gis_id);

                    Gson gson = new GsonBuilder().setPrettyPrinting().create();
                    String json = gson.toJson(polesData);

                    if (polesData != null && !polesData.isEmpty()) {

                        showAlertDialogForUncheckCondition();
                        new_ch_33.setChecked(true);

                    } else {

                        new_layout_main_33.setVisibility(View.GONE);
                    }
                }

                break;


        }
    }

